VALUES ('traceway-duckdb', 'Traceway DuckDB', 'DuckDB health of a monitored Traceway instance', 'traceway', '{"schemaVersion":1,"widgets":[{"title":"Database Size (MB)","widgetType":"area_chart","config":{"sources":[{"type":"metric","name":"traceway.duckdb.db_size_mb","aggregation":"avg"}]}},{"title":"WAL Size (MB)","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"traceway.duckdb.wal_size_mb","aggregation":"avg"}]}},{"title":"Memory Used (MB)","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"traceway.duckdb.memory_used_mb","aggregation":"avg"}]}},{"title":"Dropped Rows","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"traceway.duckdb.rows_dropped.delta","aggregation":"sum"}]}},{"title":"Insert Failures","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"traceway.duckdb.insert_failures.delta","aggregation":"sum"}]}},{"title":"Read Pool In Use","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"traceway.duckdb.read_pool.in_use","aggregation":"avg"}]}},{"title":"Read Pool Waits","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"traceway.duckdb.read_pool.wait_count.delta","aggregation":"sum"}]}},{"title":"Read Pool Wait Time (ms)","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"traceway.duckdb.read_pool.wait_ms.delta","aggregation":"sum"}]}}]}', NOW(), NOW())
